def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    if not cells:
        return out

    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)
    cmin = min(c for r, c in cells)
    cmax = max(c for r, c in cells)

    # Seed a wavefront from the occupied cell closest to each bounding-box corner.
    corners = [(rmin, cmin, 1), (rmin, cmax, 4),
               (rmax, cmin, 3), (rmax, cmax, 2)]
    seeds = []
    for cr, cc, color in corners:
        p = min(cells, key=lambda x: (abs(x[0] - cr) + abs(x[1] - cc), x))
        seeds.append((p, color))

    dist = {}
    owner = {}
    queue = []
    for (r, c), color in seeds:
        if (r, c) not in dist:
            dist[(r, c)] = 0
            owner[(r, c)] = color
            queue.append((r, c))
        elif color < owner[(r, c)]:
            owner[(r, c)] = color

    i = 0
    while i < len(queue):
        r, c = queue[i]
        i += 1
        for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if p not in cells:
                continue
            nd = dist[(r, c)] + 1
            if p not in dist:
                dist[p] = nd
                owner[p] = owner[(r, c)]
                queue.append(p)
            elif dist[p] == nd and owner[(r, c)] < owner[p]:
                owner[p] = owner[(r, c)]

    for r, c in cells:
        out[r][c] = owner.get((r, c), 1)
    return out
